const infrastructure = {
  chain: "Base",
  token: "USDC",
  escrow: "TaskEscrow",
  storage: "R2/IPFS",
  indexer: "Goldsky/The Graph",
};

const state = {
  wallet: {
    address: `0x${crypto.randomUUID().replaceAll("-", "").slice(0, 40)}`,
    balance: 25,
    escrow: 0,
    earned: 0,
  },
  reputation: 80,
  agent: {
    name: "research-node",
    skill: "项目尽调",
    runtime: "Ollama 本地模型",
    id: `agent_${crypto.randomUUID().slice(0, 8)}`,
  },
  task: null,
  step: 0,
};

const steps = [
  {
    title: "发布任务",
    body: "任务写入 Task API，预算准备进入 Base USDC 托管。",
    action: "发布任务并托管 USDC",
  },
  {
    title: "Agent 接单",
    body: "OneNode 匹配本机 Agent，签名接受任务。",
    action: "本机 Agent 接单",
  },
  {
    title: "执行任务",
    body: "Agent Runtime 调用本地模型或 OpenAI compatible API 执行。",
    action: "运行 Agent",
  },
  {
    title: "提交结果",
    body: "结果上传到 R2/IPFS，系统提交 result_hash 和 Agent 签名。",
    action: "提交结果哈希",
  },
  {
    title: "确认付款",
    body: "发布者确认后，Escrow 释放 USDC，并通过索引器更新信誉。",
    action: "确认并释放 USDC",
  },
];

const elements = {
  walletAddress: document.querySelector("#walletAddress"),
  walletBalance: document.querySelector("#walletBalance"),
  escrowBalance: document.querySelector("#escrowBalance"),
  earnedBalance: document.querySelector("#earnedBalance"),
  reputationScore: document.querySelector("#reputationScore"),
  agentForm: document.querySelector("#agentForm"),
  agentName: document.querySelector("#agentName"),
  agentSkill: document.querySelector("#agentSkill"),
  agentRuntime: document.querySelector("#agentRuntime"),
  agentCard: document.querySelector("#agentCard"),
  taskForm: document.querySelector("#taskForm"),
  taskType: document.querySelector("#taskType"),
  taskBudget: document.querySelector("#taskBudget"),
  taskPrompt: document.querySelector("#taskPrompt"),
  timeline: document.querySelector("#timeline"),
  resetBtn: document.querySelector("#resetBtn"),
};

function shortAddress(address) {
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

function money(value) {
  return value.toFixed(2);
}

function hashPayload(payload) {
  const text = JSON.stringify(payload);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return `0x${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function sign(payload) {
  return `sig_${hashPayload({ payload, agent: state.agent.id }).slice(2)}`;
}

function createTask() {
  const budget = Math.max(Number.parseFloat(elements.taskBudget.value) || 0, 0);
  if (budget <= 0 || budget > state.wallet.balance) return;

  const task = {
    id: `task_${String(Date.now()).slice(-6)}`,
    type: elements.taskType.value,
    prompt: elements.taskPrompt.value.trim(),
    budget,
    status: "escrowed",
    createdAt: new Date().toLocaleString("zh-CN", {
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    }),
  };

  task.inputHash = hashPayload(task);
  task.publisherSignature = sign({ task, role: "publisher" });

  state.wallet.balance -= budget;
  state.wallet.escrow += budget;
  state.task = task;
  state.step = 1;
  render();
}

function advanceFlow() {
  if (!state.task || state.step === 0) return;

  if (state.step === 1) {
    state.task.status = "accepted";
    state.task.worker = state.agent.name;
    state.task.acceptSignature = sign({ taskId: state.task.id, action: "accept" });
  }

  if (state.step === 2) {
    state.task.status = "running";
    state.task.executionLog = `${state.agent.runtime} 已完成 ${state.task.type}。`;
  }

  if (state.step === 3) {
    state.task.status = "submitted";
    state.task.result =
      "交付摘要：完成项目背景、代币风险、竞品格局和继续跟踪建议。高风险项：代币权限和流动性集中。";
    state.task.resultUri = `${infrastructure.storage.toLowerCase().replace("/", "-")}://${state.task.id}.json`;
    state.task.resultHash = hashPayload({
      id: state.task.id,
      result: state.task.result,
      agent: state.agent.id,
    });
    state.task.resultSignature = sign({
      taskId: state.task.id,
      resultHash: state.task.resultHash,
    });
  }

  if (state.step === 4) {
    state.task.status = "paid";
    state.wallet.escrow -= state.task.budget;
    state.wallet.earned += state.task.budget;
    state.reputation += 3;
  }

  state.step = Math.min(state.step + 1, steps.length);
  render();
}

function resetFlow() {
  state.wallet.balance = 25;
  state.wallet.escrow = 0;
  state.wallet.earned = 0;
  state.reputation = 80;
  state.task = null;
  state.step = 0;
  render();
}

function renderAgent() {
  elements.agentCard.innerHTML = `
    <strong>${state.agent.name}</strong>
    <p>${state.agent.skill} · ${state.agent.runtime}</p>
    <div class="pill-row">
      <span class="pill">${state.agent.id}</span>
      <span class="pill">ERC-8004 ready</span>
    </div>
  `;
}

function renderMetrics() {
  elements.walletAddress.textContent = shortAddress(state.wallet.address);
  elements.walletBalance.textContent = money(state.wallet.balance);
  elements.escrowBalance.textContent = money(state.wallet.escrow);
  elements.earnedBalance.textContent = money(state.wallet.earned);
  elements.reputationScore.textContent = state.reputation;
}

function renderTaskDetails() {
  if (!state.task) {
    return `
      <div class="task-card">
        <strong>还没有任务</strong>
        <p>填写上方表单并发布任务后，OneNode 会模拟调用 Task API、Base USDC Escrow、存储和索引器。</p>
      </div>
    `;
  }

  const result = state.task.result
    ? `
      <div class="pill-row">
        <span class="pill">${state.task.resultUri}</span>
        <span class="pill">${state.task.resultHash}</span>
        <span class="pill">${state.task.resultSignature}</span>
      </div>
    `
    : "";

  return `
    <div class="task-card">
      <strong>${state.task.id} · ${state.task.type} · ${state.task.status}</strong>
      <p>${state.task.prompt}</p>
      ${state.task.result ? `<p>${state.task.result}</p>` : ""}
      <div class="pill-row">
        <span class="pill">${state.task.budget} USDC</span>
        <span class="pill">${state.task.inputHash}</span>
        <span class="pill">${state.task.publisherSignature}</span>
      </div>
      ${result}
    </div>
  `;
}

function renderTimeline() {
  const cards = steps
    .map((item, index) => {
      const number = index + 1;
      const done = state.step > number || (state.task?.status === "paid" && number === steps.length);
      const active = state.step === number && state.task?.status !== "paid";
      const pending = state.step < number;
      const className = ["step", done ? "done" : "", active ? "active" : "", pending ? "pending" : ""]
        .filter(Boolean)
        .join(" ");
      const disabled = !active;

      return `
        <article class="${className}">
          <span class="step-index">${number}</span>
          <div>
            <strong>${item.title}</strong>
            <p>${item.body}</p>
          </div>
          ${
            active
              ? `<button class="step-button" type="button" data-next="true">${item.action}</button>`
              : `<button class="step-button" type="button" disabled>${done ? "完成" : "等待"}</button>`
          }
        </article>
      `;
    })
    .join("");

  elements.timeline.innerHTML = `${renderTaskDetails()}${cards}`;
}

function render() {
  renderAgent();
  renderMetrics();
  renderTimeline();
}

elements.agentForm.addEventListener("submit", (event) => {
  event.preventDefault();
  state.agent = {
    ...state.agent,
    name: elements.agentName.value.trim() || "local-agent",
    skill: elements.agentSkill.value,
    runtime: elements.agentRuntime.value,
  };
  render();
});

elements.taskForm.addEventListener("submit", (event) => {
  event.preventDefault();
  createTask();
});

elements.timeline.addEventListener("click", (event) => {
  if (!event.target.closest("[data-next]")) return;
