}

.panel-header {
  margin-bottom: 18px;
}

.split {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.stack,
.task-form {
  display: grid;
  gap: 12px;
}

.task-form {
  grid-template-columns: 1fr 130px;
  align-items: end;
}

.wide {
  grid-column: 1 / -1;
}

label {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 0.84rem;
  font-weight: 760;
}

input,
select,
textarea {
  width: 100%;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
  padding: 11px 12px;
  outline: none;
}

textarea {
  min-height: 116px;
  resize: vertical;
}

input:focus,
select:focus,
textarea:focus {
  border-color: rgba(18, 119, 103, 0.6);
  box-shadow: 0 0 0 3px rgba(18, 119, 103, 0.12);
}

.primary-button,
.ghost-button,
.step-button {
  min-height: 42px;
  padding: 0 14px;
  cursor: pointer;
  font-weight: 850;
}

.primary-button {
  color: #fff;
  background: var(--accent);
}

.ghost-button {
  border: 1px solid var(--line);
  color: var(--ink);
  background: var(--surface-2);
}

.step-button {
  min-height: 34px;
  color: #fff;
  background: var(--blue);
}

.primary-button:hover,
.ghost-button:hover,
.step-button:hover {
  filter: brightness(0.97);
}

.info-card,
.task-card,
.step {
  border: 1px solid var(--line);
  background: var(--surface-2);
  padding: 14px;
}

.info-card {
  margin-top: 14px;
}

.info-card strong,
.task-card strong,
.step strong {
  display: block;
  margin-bottom: 6px;
}

.info-card p,
.task-card p,
.step p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
  font-size: 0.9rem;
}

.timeline {
  display: grid;
  gap: 12px;
  margin-top: 20px;
}

.step {
  display: grid;
  grid-template-columns: 38px 1fr auto;
  gap: 12px;
  align-items: center;
}

.step-index {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  color: #fff;
  background: var(--accent);
  font-weight: 900;
}

.step.pending .step-index {
  background: #9ca8a3;
}

.step.done .step-index {
  background: var(--ok);
}

.step.active {
  border-color: rgba(53, 111, 159, 0.48);
  background: #f7fbff;
}

.pill-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.pill {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 9px;
  color: var(--accent);
  background: rgba(18, 119, 103, 0.1);
  font-size: 0.76rem;
  font-weight: 850;
}

.metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.metrics div {
  min-height: 86px;
