};

const baseChain = {
  chainId: "0x2105",
  chainName: "Base",
  nativeCurrency: { name: "Ether", symbol: "ETH", decimals: 18 },
  rpcUrls: ["https://mainnet.base.org"],
  blockExplorerUrls: ["https://basescan.org"],
};

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!saved) return defaultState();
    const defaults = defaultState();
    return {
      ...defaults,
      ...saved,
      wallet: { ...defaults.wallet, ...saved.wallet },
      agent: { ...defaults.agent, ...saved.agent },
      tasks: saved.tasks || [],
    };
  } catch {
    return defaultState();
  }
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function hasInjectedWallet() {
  return typeof window.ethereum !== "undefined";
}

function shortAddress(address) {
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

function money(value) {
  return Number(value).toFixed(2);
}

function hashPayload(payload) {
  const text = JSON.stringify(payload);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return `0x${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function sign(payload) {
  return `sig_${hashPayload({ payload, agent: state.agent.id }).slice(2)}`;
}

function setView(view) {
  state.view = view;
  saveState();
  render();
}

async function connectWallet() {
  if (!hasInjectedWallet()) {
    state.wallet.mode = "local";
    state.wallet.error = "未检测到浏览器钱包。请用安装了 MetaMask/Rabby/Coinbase Wallet 的浏览器，并优先通过 localhost 打开页面。";
    saveState();
    render();
    return;
  }

  try {
    const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
    const chainId = await window.ethereum.request({ method: "eth_chainId" });
    state.wallet.connectedAddress = accounts[0] || "";
    state.wallet.chainId = chainId;
    state.wallet.mode = state.wallet.connectedAddress ? "connected" : "local";
    state.wallet.error = "";
    saveState();
    render();
  } catch {
    state.wallet.mode = "local";
    state.wallet.error = "钱包连接被取消或浏览器阻止了连接请求。";
    saveState();
    render();
  }
}

async function switchToBase() {
  if (!hasInjectedWallet()) return;
  try {
    await window.ethereum.request({
      method: "wallet_switchEthereumChain",
      params: [{ chainId: baseChain.chainId }],
    });
  } catch (error) {
    if (error.code === 4902) {
      await window.ethereum.request({
        method: "wallet_addEthereumChain",
        params: [baseChain],
      });
    }
  }
  state.wallet.chainId = await window.ethereum.request({ method: "eth_chainId" });
  saveState();
  render();
}

function createTask() {
  const budget = Math.max(Number.parseFloat(elements.taskBudget.value) || 0, 0);
  const prompt = elements.taskPrompt.value.trim();
  if (!prompt || budget <= 0 || budget > state.wallet.balance) return;

  const task = {
    id: `task_${String(Date.now()).slice(-6)}`,
    type: elements.taskType.value,
    prompt,
    budget,
    status: "open",
    createdAt: new Date().toLocaleString("zh-CN"),
    inputHash: "",
    publisherSignature: "",
  };
  task.inputHash = hashPayload(task);
  task.publisherSignature = sign({ task, role: "publisher" });

  state.wallet.balance -= budget;
  state.wallet.escrow += budget;
  state.tasks.unshift(task);
  saveState();
  render();
}

function seedTasks() {
  const examples = [
    ["合约初审", "检查 ERC-20 合约 owner 权限、无限授权、暂停函数和升级代理风险。", 8],
    ["链上分析", "分析一个地址过去 30 天资金流、主要交互协议和异常转账。", 4],
    ["DAO 周报", "总结治理论坛本周提案、争议点、投票风险和建议行动。", 3],
  ];

  examples.forEach(([type, prompt, budget]) => {
    if (budget > state.wallet.balance) return;
    elements.taskType.value = type;
    elements.taskPrompt.value = prompt;
    elements.taskBudget.value = String(budget);
    createTask();
  });
}

function updateTask(id, next) {
  state.tasks = state.tasks.map((task) => (task.id === id ? { ...task, ...next } : task));
}

function acceptTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "open") return;
  updateTask(id, {
    status: "accepted",
    worker: state.agent.name,
    acceptSignature: sign({ taskId: id, action: "accept" }),
  });
  saveState();
  setView("agent");
}

async function runTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "accepted") return;
  updateTask(id, {
    status: "running",
    executionLog: `${state.agent.runtime} 正在执行 ${task.type}。`,
  });
  saveState();
  render();

  const result = await generateWithAgent(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

function submitTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "running") return;
  const result = buildResult(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

async function generateWithAgent(task) {
  if (state.agent.runtime === "Ollama 本地模型") {
    try {
      return await callOllama(task);
    } catch (error) {
      state.agent.modelStatus = `Ollama 调用失败，已回退模拟结果：${error.message}`;
      return buildResult(task);
    }
  }
  return buildResult(task);
}

async function callOllama(task) {
  const endpoint = state.agent.ollamaEndpoint.replace(/\/$/, "");
  const response = await fetch(`${endpoint}/api/generate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: state.agent.ollamaModel,
      stream: false,
      prompt: [
        "你是 OneNode 上的专业 AI Agent。请用中文交付任务结果。",
        `任务类型：${task.type}`,
        `任务内容：${task.prompt}`,
        "输出结构：摘要、关键发现、风险、建议。保持简洁但可交付。",
      ].join("\n"),
    }),
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  const text = data.response?.trim();
  if (!text) throw new Error("模型没有返回内容");
  state.agent.modelStatus = `已连接 ${state.agent.ollamaModel}`;
  return text;
}

async function testLocalModel() {
