  taskSummary: document.querySelector("#taskSummary"),
  activeTask: document.querySelector("#activeTask"),
  historyList: document.querySelector("#historyList"),
  resetBtn: document.querySelector("#resetBtn"),
  seedBtn: document.querySelector("#seedBtn"),
  testOnlineApiBtn: document.querySelector("#testOnlineApiBtn"),
};

const statusLabel = {
  open: "待接单",
  accepted: "已接单",
  running: "执行中",
  submitted: "待确认",
  paid: "已结算",
};

const demandTemplates = {
  project: {
    type: "项目快评",
    budget: "5",
    prompt: "分析一个新 Web3 项目：判断是否值得关注，说明机会等级、风险等级、代币风险、竞品和建议操作。",
  },
  token: {
    type: "Token 风险扫描",
    budget: "8",
    prompt: "扫描一个 Token：分析持仓集中度、流动性、owner 权限、黑名单/税费风险、解锁风险，并给出参与建议。",
  },
  yield: {
    type: "稳定币收益扫描",
    budget: "6",
    prompt: "寻找 1 万 USDC、低到中风险、周期 30 天的稳定币收益机会。需要列出 APY 来源、主要风险和退出条件。",
  },
  airdrop: {
    type: "空投/积分机会分析",
    budget: "4",
    prompt: "分析一个生态或项目的空投/积分机会：预期收益、成本、任务路径、风险、优先级和是否值得参与。",
  },
};

const reliableWatchlist = [
  {
    symbol: "ETH",
    name: "Ethereum",
    category: "核心结算层",
    why: "智能合约、DeFi、L2、RWA 和稳定币活动的核心基础设施，生态深度强。",
