  {
    symbol: "LINK",
    name: "Chainlink",
    category: "预言机 / 跨链基础设施",
    why: "预言机、数据源、自动化和跨链通信是 DeFi 与 RWA 的关键中间层。",
    risk: "价值捕获与协议收入、代币需求关系需要重点验证。",
    taskType: "项目深度尽调",
