      demandTemplates.airdrop.prompt,
  };
  return promptMap[prompt] || prompt;
}

function translateResult(result) {
  if (!result) return result;
  if (result.includes("结论")) {
    return "Conclusion: Needs review. Opportunity score 5/10, risk score 5/10. Suggested action: watch first; avoid high-risk actions until more data is available.";
  }
  return result;
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function hasInjectedWallet() {
  return typeof window.ethereum !== "undefined";
}

function shortAddress(address) {
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

function money(value) {
  return Number(value).toFixed(2);
}

function hashPayload(payload) {
  const text = JSON.stringify(payload);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return `0x${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function sign(payload) {
  return `sig_${hashPayload({ payload, agent: state.agent.id }).slice(2)}`;
}

function setView(view) {
  state.view = view;
  saveState();
  render();
}

async function connectWallet() {
  if (!hasInjectedWallet()) {
    state.wallet.mode = "local";
    state.wallet.error =
      "No browser wallet detected. Use a browser with MetaMask, Rabby, or Coinbase Wallet, preferably through localhost.";
    saveState();
    render();
    return;
  }

  try {
    const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
    const chainId = await window.ethereum.request({ method: "eth_chainId" });
    state.wallet.connectedAddress = accounts[0] || "";
    state.wallet.chainId = chainId;
    state.wallet.mode = state.wallet.connectedAddress ? "connected" : "local";
    state.wallet.error = "";
    saveState();
    render();
  } catch {
    state.wallet.mode = "local";
    state.wallet.error = "Wallet connection was cancelled or blocked by the browser.";
    saveState();
    render();
  }
}

