function updateTask(id, next) {
  state.tasks = state.tasks.map((task) => (task.id === id ? { ...task, ...next } : task));
}

function acceptTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "open") return;
  updateTask(id, {
    status: "accepted",
    worker: state.agent.name,
    acceptSignature: sign({ taskId: id, action: "accept" }),
  });
  saveState();
  setView("agent");
}

async function runTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "accepted") return;
  updateTask(id, {
    status: "running",
    executionLog: `${state.agent.runtime} is running ${task.type}.`,
  });
  saveState();
  render();

  const result = await generateWithAgent(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

function submitTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "running") return;
  const result = buildResult(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

async function generateWithAgent(task) {
  try {
    return await callOnlineApi(task);
  } catch (error) {
    state.agent.modelStatus = `Online agent failed; using fallback result: ${error.message}`;
    return buildResult(task);
  }
}

async function callOnlineApi(task) {
  const baseUrl = state.agent.onlineApiBase.replace(/\/$/, "");
  if (!state.agent.onlineApiKey) throw new Error("Missing API key");
  const response = await fetch(`${baseUrl}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${state.agent.onlineApiKey}`,
    },
    body: JSON.stringify({
      model: state.agent.onlineModel,
      messages: [
        {
          role: "system",
          content:
            "You are OneNode's Web3 investment and yield research agent. Produce a decision-oriented report with conclusion, opportunity score, risk score, suggested action, key reasons, risks, and data to monitor. Do not promise returns.",
        },
        {
          role: "user",
          content: `Request type: ${task.type}\nRequest: ${task.prompt}`,
        },
      ],
      temperature: 0.3,
    }),
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  const text = data.choices?.[0]?.message?.content?.trim();
  if (!text) throw new Error("No model output");
  state.agent.modelStatus = `Connected ${state.agent.onlineModel}`;
  return text;
}

async function testOnlineApi() {
  state.agent = readAgentForm();
  state.agent.modelStatus = "Testing online API...";
