function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!saved) return defaultState();
    const defaults = defaultState();
    return normalizeState({
      ...defaults,
      ...saved,
      wallet: { ...defaults.wallet, ...saved.wallet },
      agent: { ...defaults.agent, ...saved.agent },
      tasks: saved.tasks || [],
    });
  } catch {
    return defaultState();
  }
}

function normalizeState(nextState) {
  const validSkills = [
    "Investment opportunity analysis",
    "Token risk scan",
    "Yield opportunity scan",
    "Airdrop opportunity analysis",
  ];
  nextState.agent.skill = validSkills.includes(nextState.agent.skill)
    ? nextState.agent.skill
    : "Investment opportunity analysis";
  nextState.agent.runtime = "Online Agent API";
  nextState.agent.modelStatus = nextState.agent.modelStatus || "Not tested";
  nextState.wallet.error = nextState.wallet.error || "";
  return nextState;
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function hasInjectedWallet() {
  return typeof window.ethereum !== "undefined";
}

function shortAddress(address) {
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

function money(value) {
  return Number(value).toFixed(2);
}

function hashPayload(payload) {
  const text = JSON.stringify(payload);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return `0x${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function sign(payload) {
  return `sig_${hashPayload({ payload, agent: state.agent.id }).slice(2)}`;
}

function setView(view) {
  state.view = view;
  saveState();
  render();
}

async function connectWallet() {
  if (!hasInjectedWallet()) {
    state.wallet.mode = "local";
    state.wallet.error =
      "No browser wallet detected. Use a browser with MetaMask, Rabby, or Coinbase Wallet, preferably through localhost.";
    saveState();
    render();
    return;
  }

  try {
    const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
    const chainId = await window.ethereum.request({ method: "eth_chainId" });
    state.wallet.connectedAddress = accounts[0] || "";
    state.wallet.chainId = chainId;
    state.wallet.mode = state.wallet.connectedAddress ? "connected" : "local";
    state.wallet.error = "";
    saveState();
    render();
  } catch {
    state.wallet.mode = "local";
    state.wallet.error = "Wallet connection was cancelled or blocked by the browser.";
    saveState();
    render();
  }
}

async function switchToBase() {
  if (!hasInjectedWallet()) return;
  try {
    await window.ethereum.request({
      method: "wallet_switchEthereumChain",
      params: [{ chainId: baseChain.chainId }],
    });
  } catch (error) {
    if (error.code === 4902) {
      await window.ethereum.request({
        method: "wallet_addEthereumChain",
        params: [baseChain],
      });
    }
  }
  state.wallet.chainId = await window.ethereum.request({ method: "eth_chainId" });
  saveState();
  render();
}

function createTask() {
  const budget = Math.max(Number.parseFloat(elements.taskBudget.value) || 0, 0);
  const prompt = elements.taskPrompt.value.trim();
  if (!prompt || budget <= 0 || budget > state.wallet.balance) return;

  const task = {
    id: `task_${String(Date.now()).slice(-6)}`,
    type: elements.taskType.value,
    prompt,
    budget,
    status: "open",
    createdAt: new Date().toLocaleString("en-US"),
    inputHash: "",
    publisherSignature: "",
  };
  task.inputHash = hashPayload(task);
  task.publisherSignature = sign({ task, role: "publisher" });

  state.wallet.balance -= budget;
  state.wallet.escrow += budget;
  state.tasks.unshift(task);
  saveState();
  render();
}

function seedTasks() {
  const examples = [
    [
      "Project quick review",
      "Quickly assess a new L2 project: product positioning, funding, token risk, competitors, and current market traction.",
      5,
    ],
    ["Token risk scan", "Scan a Base token for holder concentration, liquidity, owner permissions, tax/blacklist risk.", 8],
    [
      "Stablecoin yield scan",
      "Find stablecoin yield opportunities for 10,000 USDC, low-to-medium risk, 30-day horizon, and list exit conditions.",
      6,
    ],
  ];

  examples.forEach(([type, prompt, budget]) => {
    if (budget > state.wallet.balance) return;
    elements.taskType.value = type;
    elements.taskPrompt.value = prompt;
    elements.taskBudget.value = String(budget);
    createTask();
  });
}

function updateTask(id, next) {
  state.tasks = state.tasks.map((task) => (task.id === id ? { ...task, ...next } : task));
}

function acceptTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "open") return;
  updateTask(id, {
    status: "accepted",
    worker: state.agent.name,
    acceptSignature: sign({ taskId: id, action: "accept" }),
  });
  saveState();
  setView("agent");
}

async function runTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "accepted") return;
  updateTask(id, {
    status: "running",
    executionLog: `${state.agent.runtime} is running ${task.type}.`,
  });
  saveState();
  render();

  const result = await generateWithAgent(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

function submitTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "running") return;
  const result = buildResult(task);
  const resultHash = hashPayload({ taskId: id, result, agent: state.agent.id });
  updateTask(id, {
    status: "submitted",
    result,
    resultUri: `r2-ipfs://${id}.json`,
    resultHash,
    resultSignature: sign({ taskId: id, resultHash }),
  });
  saveState();
  render();
}

async function generateWithAgent(task) {
  try {
    return await callOnlineApi(task);
  } catch (error) {
    state.agent.modelStatus = `Online agent failed; using fallback result: ${error.message}`;
    return buildResult(task);
  }
}

async function callOnlineApi(task) {
  const baseUrl = state.agent.onlineApiBase.replace(/\/$/, "");
  if (!state.agent.onlineApiKey) throw new Error("Missing API key");
  const response = await fetch(`${baseUrl}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${state.agent.onlineApiKey}`,
    },
    body: JSON.stringify({
      model: state.agent.onlineModel,
      messages: [
        {
          role: "system",
          content:
            "You are OneNode's Web3 investment and yield research agent. Produce a decision-oriented report with conclusion, opportunity score, risk score, suggested action, key reasons, risks, and data to monitor. Do not promise returns.",
        },
        {
          role: "user",
          content: `Request type: ${task.type}\nRequest: ${task.prompt}`,
        },
      ],
      temperature: 0.3,
    }),
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  const text = data.choices?.[0]?.message?.content?.trim();
  if (!text) throw new Error("No model output");
  state.agent.modelStatus = `Connected ${state.agent.onlineModel}`;
  return text;
}

async function testOnlineApi() {
  state.agent = readAgentForm();
  state.agent.modelStatus = "Testing online API...";
  saveState();
  render();

  try {
    const text = await callOnlineApi({
      type: "Connection test",
      prompt: "Reply with one short sentence: OneNode online agent connected.",
    });
    state.agent.modelStatus = text ? `Online API ready: ${state.agent.onlineModel}` : "Online API returned no content";
  } catch (error) {
    state.agent.modelStatus = `Online API failed: ${error.message}`;
  }
  saveState();
  render();
}

function payTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "submitted") return;
  updateTask(id, {
    status: "paid",
    paidAt: new Date().toLocaleString("en-US"),
    settlementHash: hashPayload({ taskId: id, paid: task.budget }),
  });
  state.wallet.escrow -= task.budget;
  state.wallet.earned += task.budget;
  state.reputation += 3;
  saveState();
  render();
}

function refundTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status === "paid") return;
  updateTask(id, { status: "refunded" });
  state.wallet.escrow -= task.budget;
  state.wallet.balance += task.budget;
  state.reputation = Math.max(0, state.reputation - 1);
  saveState();
  render();
}

function buildResult(task) {
  const templates = {
    "Project quick review":
      "Conclusion: Keep watching. Opportunity score 7/10, risk score 6/10. Suggested action: observe first; avoid heavy allocation. Key reasons: clear narrative but limited on-chain proof. Main risks: token permissions, concentrated liquidity, and unclear unlock schedule.",
    "Project deep research":
      "Conclusion: More diligence required. Opportunity score 6/10, risk score 7/10. Suggested action: validate team, funding, token distribution, and competitors before acting. Monitor TVL, active addresses, revenue, and unlock schedule.",
    "Token risk scan":
      "Conclusion: Proceed carefully. Opportunity score 5/10, risk score 8/10. Suggested action: small position or avoid. Risks include holder concentration, thin liquidity, owner permissions, and possible blacklist or tax logic.",
    "Stablecoin yield scan":
      "Conclusion: Low-to-medium risk pools are worth monitoring. Opportunity score 6/10, risk score 4/10. Suggested action: prioritize high-TVL pools with clear APY source and fast exit. Exit signals include abnormal APY spikes, rapid TVL outflow, or stablecoin depeg.",
    "Yield pool risk analysis":
      "Conclusion: Size positions conservatively. Opportunity score 6/10, risk score 6/10. Suggested action: verify APY source, audit status, pool TVL, depeg exposure, and contract permissions before entering.",
    "Airdrop points analysis":
      "Conclusion: Worth low-cost participation. Opportunity score 7/10, risk score 5/10. Suggested action: focus on low-cost interactions and avoid high slippage, high gas, or long lock-up tasks.",
  };
  return (
    templates[task.type] ||
    "Conclusion: More data needed. Opportunity score 5/10, risk score 5/10. Suggested action: watch first and avoid high-risk actions."
  );
}

