function renderMetrics() {
  const escrow = state.tasks
    .filter((task) => !["paid", "refunded"].includes(task.status))
    .reduce((sum, task) => sum + task.budget, 0);
  state.wallet.escrow = escrow;
  const connected = state.wallet.mode === "connected" && state.wallet.connectedAddress;
  const address = connected ? state.wallet.connectedAddress : state.wallet.address;
  const onBase = state.wallet.chainId === baseChain.chainId;
  elements.walletAddress.textContent = shortAddress(address);
  elements.walletStatus.textContent = state.wallet.error
    ? state.wallet.error
    : connected
      ? `${onBase ? "Base" : `Chain ${state.wallet.chainId}`} · Wallet connected · simulated settlement`
      : "Local wallet · simulated balance · wallet not connected";
  elements.connectWalletBtn.textContent = connected ? (onBase ? "Connected" : "Switch to Base") : "Connect";
  elements.walletBalance.textContent = money(state.wallet.balance);
  elements.escrowBalance.textContent = money(state.wallet.escrow);
  elements.earnedBalance.textContent = money(state.wallet.earned);
  elements.reputationScore.textContent = state.reputation;
}

function renderTasks() {
  const activeTasks = state.tasks.filter((task) => task.status !== "paid" && task.status !== "refunded");
  elements.taskSummary.textContent = `${activeTasks.length} active / ${state.tasks.length} total`;
  elements.taskList.innerHTML =
    activeTasks.map(renderTaskCard).join("") ||
    `<article class="task-card"><strong>No requests yet</strong><p>Submit a request to escrow budget and start agent analysis.</p></article>`;
}

function renderWatchlist() {
  elements.watchlist.innerHTML = reliableWatchlist
